{
  "name": "frontend-architect-live-invites",
  "private": true,
  "type": "module",
  "scripts": {
    "check": "playwright test"
  },
  "devDependencies": {
    "@playwright/test": "1.62.1"
  }
}

export const invitations = [
  { id: 'mia', email: 'mia@example.test', state: 'pending' },
  { id: 'tom', email: 'tom@example.test', state: 'pending' },
  { id: 'zoe', email: 'zoe@example.test', state: 'pending' },
  { id: 'lee', email: 'lee@example.test', state: 'pending' },
];
export const overview = { pending: invitations.length };

import { invitations, overview as initialOverview } from './data.mjs';
import { sendInvitation, readOverview } from './transport.mjs';
const app = document.querySelector('#app');
let rows = [...invitations], overview = initialOverview, email = '', note = '', message = '', error = '', sending = false;
function element(tag, text) { const node = document.createElement(tag); if (text) node.textContent = text; return node; }
function draw() {
  app.replaceChildren(element('h1', 'Team invitations'));
  const form = element('form'), label = element('label', 'Email'), input = element('input');
  input.type = 'email'; input.required = true; input.value = email; input.name = 'email'; label.append(input);
  input.oninput = () => { email = input.value; };
  const submit = element('button', 'Send invitation'); submit.type = 'submit'; submit.disabled = sending; form.append(label, submit);
  const status = element('p', message); status.setAttribute('role', 'status'); app.append(form, status);
  if (error) { const alert = element('p', error); alert.setAttribute('role', 'alert'); app.append(alert); }
  const section = element('section'); section.className = 'overview'; section.append(element('h2', 'Overview'));
  const total = element('p', 'Pending: ' + overview.pending); total.dataset.testid = 'overview';
  const refresh = element('button', 'Refresh overview'); refresh.onclick = async () => {
    try { overview = await readOverview(); error = ''; draw(); } catch { error = 'Overview unavailable'; draw(); }
  }; section.append(total, refresh); app.append(section);
  const list = element('ol'); list.setAttribute('aria-label', 'Invitations');
  for (const row of rows) {
    const item = element('li'); item.dataset.inviteId = row.id; item.append(element('span', row.email));
    for (const [name, delta] of [['Move earlier', -1], ['Move later', 1]]) {
      const button = element('button', name); button.onclick = () => {
        const at = rows.indexOf(row), next = at + delta;
        if (next < 0 || next >= rows.length) return;
        [rows[at], rows[next]] = [rows[next], rows[at]]; draw();
      }; item.append(button);
    }
    list.append(item);
  }
  app.append(list);
  const noteLabel = element('label', 'Team note'), textarea = element('textarea'); textarea.value = note;
  textarea.oninput = () => { note = textarea.value; }; noteLabel.append(textarea); app.append(noteLabel);
  form.onsubmit = async event => {
    event.preventDefault(); const submitted = email; sending = true; error = ''; draw();
    try {
      const result = await sendInvitation(submitted); rows.push(result.invitation);
      overview = await readOverview(); message = 'Invitation sent to ' + result.invitation.email; email = '';
    } catch { error = 'Invitation failed'; message = ''; }
    sending = false; draw(); app.querySelector('input').focus();
  };
}
draw();

import { test, expect } from '@playwright/test';
const rows = page => page.getByRole('list', { name: 'Invitations' }).locator('[data-invite-id]');
test.beforeEach(async ({ page }) => {
  await page.route('**/api/overview', route => route.fulfill({ json: { pending: 5 } }));
  await page.route('**/api/invitations', route => {
    const { email } = route.request().postDataJSON();
    return route.fulfill({ json: { invitation: { id: 'new-1', email, state: 'pending' }, receipt: { id: 'receipt-1', acceptedAt: 1730000000000 } } });
  });
});
test('a sent invitation is shown with accessible confirmation and refreshed overview', async ({ page }) => {
  await page.goto('/'); await page.getByRole('textbox', { name: 'Email', exact: true }).fill('ada@example.test');
  await page.getByRole('button', { name: 'Send invitation', exact: true }).click();
  await expect(page.getByRole('status').filter({ hasText: /sent|accepted/i }).first()).toContainText(/sent|accepted/i);
  await expect(page.getByRole('status').filter({ hasText: /sent|accepted/i }).first()).toContainText('ada@example.test');
  await expect(rows(page)).toHaveCount(5); await expect(page.getByTestId('overview')).toContainText('5');
});
test('list buttons change display order without calling the service', async ({ page }) => {
  let sends = 0; page.on('request', request => { if (request.url().endsWith('/api/invitations')) sends++; });
  await page.goto('/'); await page.locator('[data-invite-id="mia"]').getByRole('button', { name: 'Move later', exact: true }).click();
  expect(await rows(page).evaluateAll(nodes => nodes.map(node => node.dataset.inviteId))).toEqual(['tom', 'mia', 'zoe', 'lee']);
  expect(sends).toBe(0);
});
test('overview can be refreshed while an independent note stays intact', async ({ page }) => {
  await page.goto('/'); await page.getByRole('textbox', { name: 'Team note', exact: true }).fill('Ask about timezone');
  await page.getByRole('button', { name: 'Refresh overview', exact: true }).click();
  await expect(page.getByTestId('overview')).toContainText('5');
  await expect(page.getByRole('textbox', { name: 'Team note', exact: true })).toHaveValue('Ask about timezone');
});

async function read(response) {
  if (!response.ok) throw new Error('Service unavailable');
  return response.json();
}
export async function sendInvitation(email) {
  return read(await fetch('/api/invitations', {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email }),
  }));
}
export async function readOverview() {
  return read(await fetch('/api/overview'));
}

## Protect accessibility and performance

Accessibility checks:

- semantic name, role, state, and value;
- keyboard reachability and logical focus order;
- visible focus and focus restoration;
- target size and touch behavior;
- sufficient contrast and non-color state cues;
- zoom, text resizing, forced colors, and high contrast where relevant;
- `prefers-reduced-motion` and user control for persistent motion;
- announcements for asynchronous changes when required.
- a non-dragging single-pointer alternative for drag interactions;
- focus is not fully obscured by sticky or overlay content;
- repeated information is not needlessly re-entered and authentication does not
  rely only on a cognitive-function test when the applicable conformance target
  includes these WCAG 2.2 criteria.

Treat target size as a tested interaction constraint, not a visual preference.
When visual density requires a smaller visible control, preserve an adequate
click or touch area without overlapping adjacent targets.

Performance checks:

- optimize the critical user path, not isolated microbenchmarks;
- avoid unnecessary network waterfalls and duplicate requests;
- reserve space for media and async content to limit layout shift;
- virtualize or paginate only when data size demonstrates the need;
- avoid broad memoization without evidence;
- inspect rendering, layout, paint, and scripting costs for animation issues;
- measure before and after material optimization.

Use RAIL as a mental model—response, animation, idle, and load—but validate with
current product metrics and representative hardware.

